#!/usr/bin/env bash
#
# Takes the dev/test defaults out of the realm Keycloak imported from docker/keycloak/realm-ecommerce.json, which are
# public in the repository: the test users get the passwords from .env (E2E_*_PASSWORD, generated by
# generate-env.sh), and the clients for the e2e tests and Postman are disabled. Run it on the server, in the
# repository's folder, once Keycloak is up and before Caddy publishes it:
#
#   docker compose up -d --wait keycloak
#   infrastructure/contabo/scripts/harden-realm.sh
#   docker compose up -d
#
# Keycloak imports the realm only once, so what this script changes stays. It can be run again at any time.
# A stopgap until the realm file itself keeps the test users out of production.

set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/../../.."

value_of() {
  sed -n "s/^$1=//p" .env | head -n 1
}

# the passwords go to the container on its standard input, never as an argument of a command (visible to `ps`)
{
  for name in E2E_CLIENT1_PASSWORD E2E_CLIENT2_PASSWORD E2E_COURIER1_PASSWORD E2E_COURIER2_PASSWORD E2E_ADMIN_PASSWORD; do
    printf 'export %s=%q\n' "${name}" "$(value_of "${name}")"
  done
  cat <<'EOF'
set -euo pipefail

kcadm() {
  /opt/keycloak/bin/kcadm.sh "$@" --config /tmp/kcadm.config
}

# signed in to the master realm as the bootstrap admin, whose credentials the container has in its environment
kcadm config credentials --server http://localhost:8080 --realm master \
  --user "${KC_BOOTSTRAP_ADMIN_USERNAME}" --password "${KC_BOOTSTRAP_ADMIN_PASSWORD}"

set_password() {
  if [[ -z "$2" || "$2" == "$1" ]]; then
    echo "harden-realm: the password of $1 in .env is empty or the username itself" >&2
    exit 1
  fi
  kcadm set-password -r ecommerce --username "$1" --new-password "$2"
  echo "password of $1 set"
}

set_password client1 "${E2E_CLIENT1_PASSWORD}"
set_password client2 "${E2E_CLIENT2_PASSWORD}"
set_password courier1 "${E2E_COURIER1_PASSWORD}"
set_password courier2 "${E2E_COURIER2_PASSWORD}"
set_password admin "${E2E_ADMIN_PASSWORD}"

for client in e2e-tests postman; do
  id="$(kcadm get clients -r ecommerce -q clientId="${client}" --fields id --format csv --noquotes)"
  kcadm update "clients/${id}" -r ecommerce -s enabled=false
  echo "client ${client} disabled"
done

rm -f /tmp/kcadm.config
EOF
} | docker compose exec -T keycloak bash -s
